public class SecureAPIUser {
    private String apiKey;

    public SecureAPIUser(String apiKey) {
        this.apiKey = apiKey; // Uložení klíče v bezpečném konfiguračním souboru
    }

    public void fetchData() {
        String url = "https://api.example.com/data";
        String apiKey = this.apiKey; // Získání klíče z konfiguračního souboru

        // Získání klíče z konfiguračního souboru
        String apiKeyConfig = loadApiKeyFromConfig();

        // Zranitelný kód opraven: Použití proměnné místo přímého použití klíče v URL
        String requestUrl = url + "?api_key=" + apiKeyConfig;

        // Volání API
        HttpClient client = HttpClient.newHttpClient();
        HttpResponse response = client.send(new HttpRequest.Builder()
                .uri(URI.create(requestUrl))
                .build());

        // Zpracování odpovědi
        if (response.statusCode() == 200) {
            String data = EntityUtils.toString(response.getEntity());
            System.out.println(data);
        }
    }

    // Metoda pro načtení API klíče z konfiguračního souboru
    private String loadApiKeyFromConfig() {
        // Implementace načtení klíče z konfiguračního souboru
        return "your_secure_api_key_here";
    }
}
